"""Straight-line evaluation of the sum in Temme's expansion of the
incomplete gamma ratios, for igamTemme.

    python3 testdata/gen/gen_igam_temme_sum.py > zz_igamTemmeSum_gen.go

Reads igamTemmeCoef (incgamma_temme_coeffs.go: the Taylor coefficients in η
of Temme's C_k(η), from SciPy's igam_asymp_coeff.h) and emits

    igamTemmeSum(η, u) = Σ_k C_k(η) u^k,  u = 1/a,

for |η| <= ETA and a >= AMIN, with each row cut at the degree where the
terms left out sum to less than TOL · AMIN^k (TOL = 2^-56 · 0.3: |C_0| >=
0.3 there, and the row is scaled by a^-k), and the rows cut where their
bound max|C_k| · AMIN^-k falls below TOL. Every row, and the
combination of the rows in u, is evaluated by Estrin's scheme (no loop, no
branch, a dependency depth of log2 of the degree instead of the degree: the
sum costs latency, not arithmetic).
"""

import os
import re

ETA = 0.34
AMIN = 20.0
# R = exp(-z²) Σ/sqrt(2πa) is at most about 7% of the smaller of P and Q
# where igamTemme is used (|η| <= 0.34, a > 20: R/Q ~ η Σ/2 in the tails,
# 0.064 at η = 0, a = 20), so Σ (>= 0.3) to 2^-56 relative keeps its error
# below 2^-60 of the result.
TOL = 2.0 ** -56 * 0.3

here = os.path.dirname(os.path.abspath(__file__))
src = open(os.path.join(here, "..", "..", "incgamma_temme_coeffs.go")).read()
body = src[src.index("{", src.index("var igamTemmeCoef")):]
rows = []
for blk in re.findall(r"\{([^{}]*)\}", body):
    nums = re.findall(r"[-+]?\d+\.\d+(?:e[-+]\d+)?", blk)
    if nums:
        rows.append(nums)
assert len(rows) == 25 and all(len(r) == 25 for r in rows)

out = []
for k, r in enumerate(rows):
    mags = [abs(float(c)) * ETA ** n for n, c in enumerate(r)]
    if sum(mags) / AMIN ** k < TOL:
        break
    deg = len(r) - 1
    tail = 0.0
    for n in range(len(r) - 1, 0, -1):
        tail += mags[n]
        if tail >= TOL * AMIN ** k:
            break
        deg = n - 1
    out.append((k, deg, r[: deg + 1]))

def estrin(cs, var):
    """Estrin's scheme for sum cs[i] var^i, with var{m} = var^m (m a power of 2)."""
    if len(cs) == 1:
        return cs[0]
    m = 1
    while 2 * m < len(cs):
        m *= 2
    lo, hi = estrin(cs[:m], var), estrin(cs[m:], var)
    pw = var if m == 1 else "%s%d" % (var, m)
    return "(%s) + %s*(%s)" % (lo, pw, hi)


def powers(var, n):
    out = []
    m = 2
    while m < n + 1:
        prev = var if m == 2 else "%s%d" % (var, m // 2)
        out.append("\t%s%d := %s * %s" % (var, m, prev, prev))
        m *= 2
    return out


print("// Code generated by testdata/gen/gen_igam_temme_sum.py; DO NOT EDIT.")
print()
print("package special")
print()
print("// igamTemmeSum returns Σ_k C_k(η) u^k (u = 1/a) for |η| <= %g, a >= %g:" % (ETA, AMIN))
print("// rows 0..%d, row k cut at degree %s; Estrin's scheme throughout." % (len(out) - 1, ", ".join(str(d) for _, d, _ in out)))
print("func igamTemmeSum(eta, u float64) float64 {")
maxdeg = max(d for _, d, _ in out)
for line in powers("eta", maxdeg):
    print(line)
for line in powers("u", len(out) - 1):
    print(line)
for k, deg, cs in out:
    print("\tc%d := %s" % (k, estrin(cs, "eta")))
print("\treturn %s" % estrin(["c%d" % k for k, _, _ in out], "u"))
print("}")
